            <span>{card.label}</span>
            <small>{card.note}</small>
          </div>
          <strong>
            {card.key === "total_amount_outstanding"
              ? summary.total_amount_outstanding
              : summary[card.key].toString()}
          </strong>
        </article>
      ))}
    </section>
  );
}

